//getting the total info about the api using promises
// select the specific button we care about (dog image fetch)
let button = document.querySelector("#dog-btn");
let url1 = "https://dog.ceo/api/breeds/image/random";

button.addEventListener("click", async () => {
    let link = await getImage();
    let img = document.querySelector("#result");
    img.src=link;
   // img.setAttribute("src", link); // alternative way to set the image source
});

async function getImage() {
    try {
        let  response = await axios.get(url1);
        console.log(response);              // inspect if you want
        return response.data.message;
    } catch (e) {
        console.log("error", e);
        return "no image found";
    }
}
